// Minimal local D3-compatible helpers used by this project.
// Keeps the interface offline for ESP32 access-point networks without internet.
(function () {
  const SVG_NS = 'http://www.w3.org/2000/svg';

  class Selection {
    constructor(nodes) {
      this.nodes = nodes;
    }

    attr(name, value) {
      this.nodes.forEach((node, index) => {
        const nextValue = typeof value === 'function' ? value(node.__data__, index) : value;
        node.setAttribute(name, nextValue);
      });
      return this;
    }

    append(tagName) {
      const created = [];
      this.nodes.forEach(node => {
        const child = document.createElementNS(SVG_NS, tagName);
        child.__data__ = node.__data__;
        node.appendChild(child);
        created.push(child);
      });
      return new Selection(created);
    }

    selectAll(selector) {
      return new DataJoin(this.nodes, selector);
    }

    text(value) {
      this.nodes.forEach((node, index) => {
        node.textContent = typeof value === 'function' ? value(node.__data__, index) : value;
      });
      return this;
    }
  }

  class DataJoin {
    constructor(parents, selector) {
      this.parents = parents;
      this.selector = selector;
      this.values = [];
    }

    data(values) {
      this.values = values;
      return this;
    }

    join(tagName) {
      const parent = this.parents[0];
      if (!parent) return new Selection([]);

      parent.querySelectorAll(this.selector).forEach(node => node.remove());

      const created = this.values.map(value => {
        const child = document.createElementNS(SVG_NS, tagName);
        child.__data__ = value;
        parent.appendChild(child);
        return child;
      });

      return new Selection(created);
    }
  }

  function select(selector) {
    const node = typeof selector === 'string' ? document.querySelector(selector) : selector;
    return new Selection(node ? [node] : []);
  }

  function hierarchy(data, depth = 0, parent = null) {
    const node = {
      data,
      depth,
      parent,
      children: (data.children || []).map(child => hierarchy(child, depth + 1, null)),
      descendants() {
        const items = [this];
        this.children.forEach(child => items.push(...child.descendants()));
        return items;
      },
      links() {
        return this.descendants()
          .filter(child => child.parent)
          .map(child => ({ source: child.parent, target: child }));
      },
    };
    node.children.forEach(child => { child.parent = node; });
    return node;
  }

  function tree() {
    let height = 1;
    let width = 1;

    function layout(root) {
      const nodes = root.descendants();
      const maxDepth = Math.max(...nodes.map(node => node.depth), 1);

      function sortChildren(node) {
        node.children.sort((a, b) => {
          if (a.data.edgeInPath !== b.data.edgeInPath) return a.data.edgeInPath ? -1 : 1;
          if (a.data.row !== b.data.row) return a.data.row - b.data.row;
          return a.data.col - b.data.col;
        });
        node.children.forEach(sortChildren);
      }

      sortChildren(root);

      const leaves = nodes.filter(node => node.children.length === 0);
      const leafStep = leaves.length > 1 ? height / (leaves.length - 1) : 0;
      let leafIndex = 0;

      function assignX(node) {
        if (node.children.length === 0) {
          node.x = leaves.length > 1 ? leafIndex * leafStep : height / 2;
          leafIndex += 1;
        } else {
          node.children.forEach(assignX);
          node.x = node.children.reduce((sum, child) => sum + child.x, 0) / node.children.length;
        }
        node.y = (width / maxDepth) * node.depth;
      }

      assignX(root);
      return root;
    }

    layout.size = function (nextSize) {
      height = nextSize[0];
      width = nextSize[1];
      return layout;
    };

    return layout;
  }

  window.d3 = { select, hierarchy, tree };
})();
